const envelope = $json;
const candidate = envelope && typeof envelope === 'object' && !Array.isArray(envelope)
  ? (envelope.body ?? envelope)
  : null;

const errors = [];
if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) {
  errors.push('payload must be a JSON object');
}

const body = candidate && typeof candidate === 'object' && !Array.isArray(candidate) ? candidate : {};
const limits = {
  name: 120,
  email: 254,
  company: 160,
  message: 5000,
  budget: 120,
  timeline: 120,
  source: 120
};

const normalize = (value) => value
  .normalize('NFKC')
  .replace(/[\u0000-\u001F\u007F]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const readString = (field, required = false) => {
  const exists = Object.prototype.hasOwnProperty.call(body, field) && body[field] !== null;
  if (!exists) {
    if (required) errors.push(`${field} is required`);
    return '';
  }

  if (typeof body[field] !== 'string') {
    errors.push(`${field} must be a string`);
    return '';
  }

  const value = normalize(body[field]);
  if (required && !value) errors.push(`${field} is required`);
  if (value.length > limits[field]) errors.push(`${field} exceeds ${limits[field]} characters`);
  return value.slice(0, limits[field]);
};

let serializedLength = 0;
try {
  serializedLength = JSON.stringify(body).length;
} catch (_) {
  errors.push('payload must be JSON serializable');
}
if (serializedLength > 12000) errors.push('payload exceeds 12000 characters');

const lead = {
  name: readString('name', true),
  email: readString('email').toLowerCase(),
  company: readString('company'),
  message: readString('message', true),
  budget: readString('budget'),
  timeline: readString('timeline'),
  source: readString('source')
};

if (lead.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(lead.email)) {
  errors.push('email is invalid');
}

const untrustedText = Object.values(lead).join(' ');
const injectionSignals = [
  /ignore\s+(all\s+)?(previous|prior|above|earlier)\s+(instructions?|messages?|rules?)/i,
  /forget\s+(all\s+)?(previous|prior|above|earlier)\s+(instructions?|messages?|rules?)/i,
  /(reveal|show|print|repeat|expose)\b.{0,40}\b(system|developer)\s+(prompt|message|instructions?)/i,
  /act\s+as\s+(the\s+)?(system|developer|administrator)/i,
  /(override|bypass|disregard)\b.{0,30}\b(instructions?|rules?|policy)/i,
  /(return|output|respond with)\b.{0,60}\binstead\b/i,
  /do\s+not\s+follow\b.{0,40}\b(instructions?|rules?)/i,
  /prompt\s*injection/i,
  /jailbreak/i,
  /<\/?system>/i,
  /\[(system|developer)\]/i,
  /begin\s+(system|developer)\s+(prompt|message)/i
];
const suspectedPromptInjection = injectionSignals.some((pattern) => pattern.test(untrustedText));

return [{
  json: {
    valid: errors.length === 0,
    errors: [...new Set(errors)],
    lead,
    security: { suspected_prompt_injection: suspectedPromptInjection },
    request_id: String($execution?.id ?? ''),
    received_at: new Date().toISOString()
  }
}];

const raw = $json.output ?? $json;
const source = $('Validate and Normalize Input').first().json;

const clampInt = (value, min, max) => {
  const number = Number(value);
  if (!Number.isFinite(number)) return min;
  return Math.min(max, Math.max(min, Math.round(number)));
};
const cleanText = (value, max) => String(value ?? '')
  .replace(/[\u0000-\u001F\u007F]/g, ' ')
  .replace(/<[^>]*>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, max);
const limitWords = (value, maxWords) => {
  const words = cleanText(value, 1500).split(/\s+/).filter(Boolean);
  return words.slice(0, maxWords).join(' ');
};

const modelBreakdown = {
  service_fit: clampInt(raw.service_fit_score, 0, 40),
  budget_authority: clampInt(raw.budget_authority_score, 0, 25),
  urgency: clampInt(raw.urgency_score, 0, 20),
  requirements_clarity: clampInt(raw.requirements_clarity_score, 0, 15)
};

const spamDetected = raw.spam_detected === true;
const breakdown = spamDetected
  ? { service_fit: 0, budget_authority: 0, urgency: 0, requirements_clarity: 0 }
  : modelBreakdown;
const leadScore = Object.values(breakdown).reduce((sum, value) => sum + value, 0);
const category = spamDetected
  ? 'Spam'
  : leadScore >= 80
    ? 'Hot'
    : leadScore >= 60
      ? 'Warm'
      : 'Cold';

let confidence = clampInt(raw.confidence, 0, 100);
if (source.security.suspected_prompt_injection === true) confidence = Math.min(confidence, 60);
const nearBoundary = !spamDetected && [60, 80].some((boundary) => Math.abs(leadScore - boundary) <= 5);
let requiresHumanReview = raw.requires_human_review === true
  || source.security.suspected_prompt_injection === true
  || confidence < 70
  || nearBoundary;

if (spamDetected && confidence < 85) requiresHumanReview = true;

const seenPainPoints = new Set();
const painPoints = (Array.isArray(raw.pain_points) ? raw.pain_points : [])
  .map((value) => cleanText(value, 200))
  .filter((value) => value && !seenPainPoints.has(value.toLowerCase()) && seenPainPoints.add(value.toLowerCase()))
  .slice(0, 10);

let suggestedReply = spamDetected
  ? 'No reply recommended.'
  : limitWords(raw.suggested_reply, 150);
if (!suggestedReply) {
  suggestedReply = spamDetected
    ? 'No reply recommended.'
    : 'Thank you for reaching out. We would like to understand your requirements in more detail. Would you be available for a 15-minute discovery call?';
  requiresHumanReview = true;
}

let summaryReason = cleanText(raw.summary_reason, 300);
if (!summaryReason) {
  summaryReason = 'The automated assessment did not provide a usable summary.';
  requiresHumanReview = true;
}

return [{
  json: {
    success: true,
    result: {
      lead_score: leadScore,
      category,
      score_breakdown: breakdown,
      spam_detected: spamDetected,
      summary_reason: summaryReason,
      pain_points: painPoints,
      suggested_reply: suggestedReply,
      confidence,
      requires_human_review: requiresHumanReview
    },
    meta: {
      request_id: source.request_id,
      received_at: source.received_at,
      workflow_version: '1.1.0',
      model_provider: 'Google Gemini',
      automated_assessment: true
    }
  }
}];
